###############################################################################
## diagnostics-lambda.R
##
## Finite-sample diagnostics for the estimated guarded-augmentation matrix
## Lambda(hat), mapped ONE-TO-ONE onto the reported plane-study replicates.
##
## Every reported replicate in <results/> was generated by
##     set.seed(seed); data_aft_int(n, c_int, p.c = 1.5)
## inside simcalc_theta_efficiency().  gen_data_fast() below draws the same
## random variables in the same order as data_aft_int() -- the per-subject
## conditional-mean integrals that data_aft_int() also computes use no RNG and
## are not needed for Lambda or the weights -- so reseeding with each replicate's
## own seed reproduces that replicate's exact data set.  For each reported file
## we parse (n, c_int, seed), regenerate the data, and compute the diagnostics.
## The script also re-reads the stored censoring rate from a random subset of
## files and checks it against the regenerated rate, to confirm the mapping is
## exact.
##
## No estimator results are changed.  The estimator applies no regularization:
## the matrix is inverted directly (solve), and a singular fit is recorded as a
## failed replicate rather than patched.
##
## Usage:
##   Rscript diagnostics-lambda.R            # all reported replicates
##   Rscript diagnostics-lambda.R 500        # first 500 files only (quick test)
###############################################################################

suppressMessages({ library(survival); library(dplyr) })

args        <- commandArgs(TRUE)
max_files   <- if (length(args) >= 1) as.integer(args[1]) else Inf
results_dir <- "results"            # reported plane-study results
p.c         <- 1.5
rcond_tol   <- 1e-10
extreme_wt  <- 10
n_validate  <- 500                  # files to check regen vs stored censoring
out_csv     <- "../Diagnostics-Revision/lambda-diagnostics.csv"

## ---------------------------------- faithful (RNG-identical) data generator
gen_data_fast <- function(nSubjects, c_int, p.c){
  epsilon_sig <- 1; beta.vec <- c(1, 1, 1)
  int <- cbind(rep(1, nSubjects))
  Z   <- rnorm(nSubjects, 0, 1)
  A   <- rnorm(nSubjects, 2, 1)
  p.x <- 0.5; gamma.x.vec <- c(0.1, 0.1)
  linPred_z  <- cbind(int, Z) %*% gamma.x.vec
  errors.x.g <- log(rweibull(nSubjects, 1, 1))
  X   <- exp(linPred_z + p.x * errors.x.g); AX <- A - X
  er  <- rnorm(nSubjects, 0, epsilon_sig)
  y   <- cbind(int, AX, Z) %*% beta.vec + er
  gamma.vec  <- c(c_int, 0.1, 0.1)
  linPred_yz <- cbind(int, y, Z) %*% gamma.vec
  errors.g   <- log(rweibull(nSubjects, 1, 1))
  C   <- exp(linPred_yz + p.c * errors.g)
  D   <- as.numeric(X <= C); W <- pmin(X, C); AW <- A - W
  dat <- data.frame(y = y, Z = Z, D = D, A = A, X = X, AX = AX,
                    C = C, W = W, AW = AW)
  wr  <- survreg(Surv(W, 1 - D) ~ y + Z, data = dat, dist = "w")
  lp  <- predict(wr, dat); gamma <- 1 / wr$scale
  dat$myp_ywz <- exp(-(dat$W / lp)^gamma)
  dat
}

## ---------------------- part1, part2, Lambda (verbatim, vectorized) --------
lambda_pieces <- function(dat){
  myp <- dat$myp_ywz; D <- dat$D
  fit <- lm(y ~ AW + Z, data = dat, weights = D / myp)
  theta <- as.numeric(coef(fit)); psi <- summary(fit)$sigma
  sdXZ <- sd(dat$W[D == 1]); meanXZ <- mean(dat$W[D == 1])
  Amat <- model.matrix(~ A + Z, data = dat)
  Xmat <- model.matrix(y ~ AW + Z, data = dat)
  Y <- dat$y
  e_star   <- as.numeric(Y - Amat %*% theta)
  a <- -1/(2*sdXZ^2) - theta[2]^2/(2*psi^2)
  b <- meanXZ/sdXZ^2 - theta[2]*e_star/psi^2
  mu_star  <- -b/(2*a)
  sd2_star <- (sdXZ^2*psi^2)/(psi^2 + theta[2]^2*sdXZ^2)
  beta0_star <- (theta[2]*mu_star + e_star)/psi^2
  beta1_star <- (-theta[2]*(sd2_star + mu_star^2) +
                   mu_star*(Amat[,2]*theta[2] - e_star) + Amat[,2]*e_star)/psi^2
  beta2_star <- Amat[,3]*beta0_star
  PH <- cbind(beta0_star, beta1_star, beta2_star)
  e_cc <- as.numeric(Y - Xmat %*% theta)
  CC <- (e_cc/psi^2) * Xmat
  w1 <- (1 - D/myp)*(D/myp); w2 <- (1 - D/myp)^2
  list(part1 = crossprod(w1*CC, PH), part2 = crossprod(PH, w2*PH),
       myp = myp, D = D)
}

## -------------------------------------------------- one replicate by seed ---
one_rep <- function(n, c_int, seed){
  set.seed(seed)
  dat <- tryCatch(gen_data_fast(n, c_int, p.c), error = function(e) NULL)
  if (is.null(dat)) return(NULL)
  pcen <- 1 - mean(dat$D)
  pc <- tryCatch(lambda_pieces(dat), error = function(e) NULL)
  base <- data.frame(seed = seed, n = n, c_int = c_int, pcen = pcen)
  if (is.null(pc))
    return(cbind(base, kappa_part2 = NA, rcond_part2 = NA, kappa_lambda = NA,
                 singular = 1, min_myp = NA, max_wt = NA, ess_frac = NA,
                 frac_extreme = NA))
  part1 <- pc$part1; part2 <- pc$part2
  rc  <- tryCatch(rcond(part2), error = function(e) 0)
  kp2 <- tryCatch(kappa(part2, exact = TRUE), error = function(e) Inf)
  Lam <- tryCatch(-part1 %*% solve(part2), error = function(e) NULL)
  singular <- as.numeric(is.null(Lam) || !is.finite(rc) || rc < rcond_tol)
  kpL <- if (is.null(Lam)) Inf else tryCatch(kappa(Lam, exact = TRUE),
                                             error = function(e) Inf)
  myp <- pc$myp; D <- pc$D; w_obs <- (1/myp)[D == 1]
  cbind(base, kappa_part2 = kp2, rcond_part2 = rc, kappa_lambda = kpL,
        singular = singular, min_myp = min(myp[D == 1]), max_wt = max(w_obs),
        ess_frac = (sum(w_obs)^2/sum(w_obs^2))/length(w_obs),
        frac_extreme = mean(w_obs > extreme_wt))
}

## ---------------------------------------- enumerate reported replicates -----
files <- list.files(results_dir, pattern = "^est_results_n_[0-9]+_.*_seed_[0-9]+\\.csv$")
if (is.finite(max_files)) files <- head(files, max_files)
message("Reported replicates found: ", length(files))

## parse (n, c_int, seed) from each filename
m <- regmatches(files, regexec("^est_results_n_([0-9]+)_(.+)_seed_([0-9]+)\\.csv$", files))
parsed <- do.call(rbind, lapply(m, function(x)
  data.frame(n = as.integer(x[2]), c_int = as.numeric(x[3]), seed = as.integer(x[4]))))
parsed$file <- files

## random subset to validate regen vs stored censoring rate
set.seed(1)
val_idx <- sample(seq_len(nrow(parsed)), min(n_validate, nrow(parsed)))

## ----------------------------------------------------------------- run ------
rows <- vector("list", nrow(parsed)); val_diff <- numeric(0)
t0 <- Sys.time()
for (i in seq_len(nrow(parsed))) {
  pr <- parsed[i, ]
  res <- one_rep(pr$n, pr$c_int, pr$seed)
  rows[[i]] <- res
  if (i %in% val_idx && !is.null(res)) {
    stored <- tryCatch(read.csv(file.path(results_dir, pr$file))$pcen[1],
                       error = function(e) NA)
    if (!is.na(stored)) val_diff <- c(val_diff, abs(stored - res$pcen))
  }
  if (i %% 2000 == 0) message(sprintf("  %d / %d", i, nrow(parsed)))
}
diag_df <- do.call(rbind, rows)
dir.create(dirname(out_csv), showWarnings = FALSE, recursive = TRUE)
write.csv(diag_df, out_csv, row.names = FALSE)

message("Wrote ", out_csv, " with ", nrow(diag_df), " rows in ",
        round(difftime(Sys.time(), t0, units = "mins"), 2), " min.")
message(sprintf("Reproduction check (%d files): max |stored pcen - regen pcen| = %.2e",
                length(val_diff), if (length(val_diff)) max(val_diff) else NA))
